.standard_normal((m, k)).astype(np.float32)\n48:         x = rng.standard_normal(k)\n49:         # Mix a weight direction with an independently sampled direction.\n50:         direction = w.astype(np.float64).sum(axis=0)\n51:         direction /= np.linalg.norm(direction)\n52:         x /= np.linalg.norm(x)\n53:         x = cfg[\"mix\"] * direction + (1.0 - cfg[\"mix\"]) * x\n54:         wf = w.astype(np.float64)\n55:         scale = np.max(np.abs(wf), axis=1, keepdims=True) / 7.0\n56:         residual = (np.clip(np.floor(wf / scale + 0.5), -7, 7) * scale - wf).sum(axis=0)\n57:         residual /= np.linalg.norm(residual)\n58:         x += cfg[\"residual\"] * residual\n59:         return tensor(x), tensor(w)\n60:     t, d = cfg[\"t\"], cfg[\"d\"]\n61:     a = np.full((t, d), cfg[\"decay\"], dtype=np.float64)\n62:     b = rng.standard_normal((t, d)) * cfg[\"noise\"]\n63:     b += cfg[\"bias\"]\n64:     return tensor(a), tensor(b)",
